import{z as o,x as E,o as r,c as s,q as A,j as i,D as e,d as n,s as l,S as h,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"透镜与数值孔径","description":"","frontmatter":{"title":"透镜与数值孔径","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lens-na.md","filePath":"litho/lens-na.md","lastUpdated":1791413859000}'),p={name:"litho/lens-na.md"};function d(B,a,N,b,f,c){const m=E("Mermaid");return r(),s("div",null,[a[2]||(a[2]=A('<h1 id="透镜与数值孔径" tabindex="-1">透镜与数值孔径 <a class="header-anchor" href="#透镜与数值孔径" aria-label="Permalink to &quot;透镜与数值孔径&quot;">​</a></h1><div class="epigraph"><p>数值孔径是物镜在像方（或物方约定下）能接收的最大 $n\\sin\\theta$；它把空间频率轴上的截止写成一个可写入镜头合同的数。</p><footer>—— 归纳自 Abbe 正弦条件与 Mack, Fundamental Principles of Optical Lithography 对 NA 的定义</footer></div><p><a href="/litho/pupil-apodization">上一课</a>（光瞳滤波与切趾）。在此之上，掩模收成空间频率，并指出均匀介质里可传播的上限是 \\(n/\\lambda\\)。缺口是：投影物镜并不是整块均匀介质，它只收集进入入瞳的那一段频谱。本课引入数值孔径 \\(\\mathrm{NA}=n\\sin\\theta\\)，把「进得去的最高空间频率」写成 \\(\\mathrm{NA}/\\lambda\\)。照明如何填充这个光瞳，留给<a href="/litho/partial-coherence">部分相干</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>衍射级已经按角度排好。没有光瞳半径，就无法回答「一级还在不在」。显微镜和投影光刻都用同一个几何量：边缘光线与光轴的夹角 \\(\\theta\\)，乘上该侧介质的折射率 \\(n\\)。这个乘积叫数值孔径。若只写 \\(\\sin\\theta\\) 而丢掉 \\(n\\)，浸没看起来像作弊；若只写「镜头很大」而不写 \\(\\theta\\)，空间频率截止无法代入公式。</p><p><span class="marginnote">直觉类比：NA 像漏斗的开口角——样品出射的光锥多陡还能被收进去。开口越大，收进来的「方向信息」越多，细节越细；但收得越斜，离焦时上下晃动越敏感，这是后面焦深惩罚埋下的种子。</span></p><p>缺口因此是给上一课的频率轴装一个硬截止，而不是开始谈临界尺寸。\\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\) 仍要等到矢量成像之后的产线判据课。</p><h3 id="na-必须带介质的-n" tabindex="-1">NA 必须带介质的 n <a class="header-anchor" href="#na-必须带介质的-n" aria-label="Permalink to &quot;NA 必须带介质的 n&quot;">​</a></h3><p>像方 \\(\\mathrm{NA}=n\\sin\\theta\\)，其中 \\(\\theta\\) 是像方边缘光线角，\\(n\\) 是像方最后一段介质的折射率：干式是空气 \\(\\approx 1\\)，浸没是水 \\(\\approx 1.44\\)。同一个玻璃镜头，把最后一段换成水，并不自动把旧 \\(\\mathrm{NA}\\) 乘上 1.44——那是浸没课的设计问题。本课只钉定义：截止频率用的是成像侧的 \\(n\\sin\\theta\\)，与<a href="/litho/em-wave-index">第一课</a>的 \\(n\\) 是同一个符号。</p><p><span class="marginnote">数字实例：\\(\\mathrm{NA}=1.35\\) 的浸没镜头，水中 \\(n\\approx1.44\\)，则 \\(\\sin\\theta=1.35/1.44\\approx0.94\\)，\\(\\theta\\approx70°\\)——边缘光线已经非常斜。干式空气 \\(n\\approx1\\) 时 NA 封顶在 1 附近，这就是浸没把 0.93 抬到 1.35 的含义。</span></p><p><span class="marginnote">投影光刻的缩比 \\(\\beta\\)（常见 \\(4\\times\\)，即 \\(|\\beta|=1/4\\)）把物方 NA 与像方 NA 连在一起：物方立体角更小。合同上的 \\(\\mathrm{NA}\\) 默认指像方，也就是晶圆侧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阿贝正弦条件要求理想成像满足 \\(n_o x_o\\sin\\theta_o=n_i x_i\\sin\\theta_i\\)。在固定缩比下，它保证离轴视场不引入多余彗差，并把物方、像方的 \\(n\\sin\\theta\\) 锁成一对。光瞳平面是空间频率的坐标系：径向坐标 \\(\\rho\\) 归一到 1 代表 \\(|\\mathbf{f}|=\\mathrm{NA}/\\lambda\\)。光瞳函数在 \\(\\rho\\le 1\\) 内取复透过率（含像差），在 \\(\\rho\\gt 1\\) 为零。</p><p>点物的像是这个光瞳的夫琅禾费衍射，圆孔时即艾里斑。本课需要艾里斑只是为了承认：有限 \\(\\mathrm{NA}\\) 给出有限的脉冲响应宽度，宽度正比于 \\(\\lambda/\\mathrm{NA}\\)。比例系数留给瑞利课的 \\(k_1\\)；这里不把 0.61 写进产线公式。</p><h3 id="光瞳里装的是频率-不是「亮度」" tabindex="-1">光瞳里装的是频率，不是「亮度」 <a class="header-anchor" href="#光瞳里装的是频率-不是「亮度」" aria-label="Permalink to &quot;光瞳里装的是频率，不是「亮度」&quot;">​</a></h3><p>入瞳半径增大，意味着更斜的平面波也能进镜头，也就是更高的 \\(f\\)。光源把光瞳填得满不满，是照明 \\(\\sigma\\)，不是 \\(\\mathrm{NA}\\)。把两者混成「孔径越大越亮」，会把收集角与填充因子搅在一起。本课的 \\(\\mathrm{NA}\\) 只约束投影成像通道；照明孔径另写。</p><p><span class="marginnote">高 \\(\\mathrm{NA}\\) 时边缘光线的偏振与能量沉积不再是标量艾里斑能概括的。那是<a href="/litho/vector-imaging">矢量成像</a>的缺口。本课仍用标量光瞳，以便先把截止频率钉死。</span></p>',17)),(r(),i(h,null,{default:e(()=>[l(m,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREQ%5B%22%E7%A9%BA%E9%97%B4%E9%A2%91%E7%8E%87%20f%22%5D%20--%3E%20CUT%5B%22%E6%88%AA%E6%AD%A2%20%7Cf%7C%20%E2%89%A4%20NA%2F%CE%BB%22%5D%0A%20%20NA%5B%22NA%20%3D%20n%20sin%CE%B8%22%5D%20--%3E%20CUT%0A%20%20CUT%20--%3E%20PUP%5B%22%E5%85%89%E7%9E%B3%E5%87%BD%E6%95%B0%20%CF%81%E2%89%A41%22%5D%0A%20%20PUP%20--%3E%20AIRY%5B%22%E7%82%B9%E6%89%A9%E6%95%A3%20%2F%20%E8%89%BE%E9%87%8C%E6%96%91%22%5D%0A%20%20PUP%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%85%A7%E6%98%8E%E5%A6%82%E4%BD%95%E5%A1%AB%E5%85%89%E7%9E%B3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[n("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"掩模衍射级落在光瞳上的位置由 \\(f=n\\sin\\theta/\\lambda\\) 决定。\\(\\mathrm{NA}\\) 越大，同一周期 \\(p\\) 的一级越靠近光瞳内部，两束干涉的调制越稳。\\(\\mathrm{NA}\\) 不够，一级被挡，只剩零级，空中像变平。这就是「镜头决定分辨率」的频率机制，尚未引入工艺因子。",-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"常见误区：以为「镜头口径毫米数越大分辨率越高」。分辨率由 \\(\\mathrm{NA}=n\\sin\\theta\\) 决定，不是镜筒粗细——焦距长的镜头口径大，\\(\\theta\\) 未必大。把口径当 NA，是把「大」错当成了「准」。")],-1)),(r(),i(h,null,{default:e(()=>[l(m,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%8E%A9%E6%A8%A1%E5%91%A8%E6%9C%9F%20p%22%5D%20--%3E%20F%5B%22%E4%B8%80%E7%BA%A7%E9%A2%91%E7%8E%87%20%E2%89%88%201%2Fp%22%5D%0A%20%20F%20--%3E%20Q%7B%221%2Fp%20%E2%89%A4%20NA%2F%CE%BB%20%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E4%B8%80%E7%BA%A7%E5%9C%A8%E5%85%89%E7%9E%B3%E5%86%85%22%7C%20TWO%5B%22%E9%9B%B6%E7%BA%A7%20%2B%20%E4%B8%80%E7%BA%A7%E5%B9%B2%E6%B6%89%22%5D%0A%20%20TWO%20--%3E%20IMG%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E6%9C%89%E8%B0%83%E5%88%B6%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B6%85%E5%87%BA%E6%88%AA%E6%AD%A2%22%7C%20ZERO%5B%22%E5%8F%AA%E5%89%A9%E9%9B%B6%E7%BA%A7%22%5D%0A%20%20ZERO%20--%3E%20FLAT%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E5%8F%98%E5%B9%B3%EF%BC%8C%E5%9B%BE%E5%BD%A2%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20BIGNA%5B%22%E6%8A%AC%20NA%22%5D%20--%3E%20Q%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p>焦深尚未正式定义，但几何上已经能看见惩罚：\\(\\theta\\) 变大，离焦时边缘光线的额外光程涨得更快。定量式子 \\(\\mathrm{DOF}\\propto\\lambda/\\mathrm{NA}^2\\) 是<a href="/litho/depth-of-focus">焦深</a>课的缺口；本课只要求记住：抬 \\(\\mathrm{NA}\\) 不是免费的轴向宽容度。</p><h3 id="折反射与反射物镜用同一-na" tabindex="-1">折反射与反射物镜用同一 NA <a class="header-anchor" href="#折反射与反射物镜用同一-na" aria-label="Permalink to &quot;折反射与反射物镜用同一 NA&quot;">​</a></h3><p>DUV 投影物镜是折射或折反射，EUV 是多层膜反射镜。无论折还是反射，合同里的 \\(\\mathrm{NA}\\) 仍是像方 \\(n\\sin\\theta\\)。EUV 的 \\(n=1\\)（真空），\\(\\mathrm{NA}=0.33\\) 或 High-NA 的 \\(0.55\\)，与浸没的 \\(1.35\\) 可以写在同一根轴上比较截止频率，不能比较「镜子张数」。本课不进入 EUV 膜系。</p><p>点物的像是光瞳的夫琅禾费衍射，圆孔时即艾里斑。本课需要它只为承认：有限 \\(\\mathrm{NA}\\) 给出有限的脉冲响应宽度，宽度正比于 \\(\\lambda/\\mathrm{NA}\\)。比例系数留给瑞利课的 \\(k_1\\)；这里不把 0.61 写进产线公式。</p><p><span class="marginnote">投影缩比 \\(\\beta\\)（常见 \\(4\\times\\)）把物方 NA 与像方 NA 连在一起：物方立体角更小。合同上的 \\(\\mathrm{NA}\\) 默认指像方，也就是晶圆侧。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(\\mathrm{NA}\\) 不包含套刻、光源功率、胶对比度。也不要把镜头口径的毫米数当成 \\(\\mathrm{NA}\\)：同样口径，工作距离和焦距不同，\\(\\theta\\) 就不同。像差使光瞳函数带相位，截止频率仍是 \\(\\mathrm{NA}/\\lambda\\)，但调制传递会低于理想圆孔；像差预算是镜头工程，不是本课的定义。</p><p>后课需要用到的只是：投影系统是 \\(\\mathrm{NA}/\\lambda\\) 的低通，晶圆侧 \\(\\mathrm{NA}=n\\sin\\theta\\)，光瞳径向坐标按此归一。照明填充、相干因子、空中像对比度，一律往后推。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{NA}=n\\sin\\theta\\) 给出空间频率截止 \\(\\mathrm{NA}/\\lambda\\)。</li><li>合同 \\(\\mathrm{NA}\\) 指晶圆侧；缩比把物方角压小。</li><li>光瞳是频率平面，不是亮度旋钮；照明填充是另一课。</li><li>抬 \\(\\mathrm{NA}\\) 改善截止，同时恶化离焦敏感，焦深公式下一课再写。</li><li>本课不写 \\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\)。</li><li>出处：Abbe 正弦条件；Mack, <em>Fundamental Principles of Optical Lithography</em>；Born &amp; Wolf 对孔径与衍射极限的讨论。</li></ul>',10))])}const D=o(p,[["render",d]]);export{_ as __pageData,D as default};
